const totalResponses = 6;
const chartContainer = document.querySelector("#surveyCharts");
const languageSelect = document.querySelector("#languageSelect");

function renderCharts(language) {
  const questions = translations[language].chartQuestions;
  chartContainer.innerHTML = questions.map((question, index) => {
    const rows = question[1].map(([label, count]) => {
      const percent = (count / totalResponses) * 100;
      return `<div class="chart-row">
        <div class="chart-label-line"><span class="chart-label">${label}</span><span class="chart-value">${count}/6 · ${percent.toFixed(1)}%</span></div>
        <div class="bar-track" role="img" aria-label="${label}: ${count} of 6, ${percent.toFixed(1)} percent"><div class="bar-fill" style="width:${percent}%"></div></div>
      </div>`;
    }).join("");
          return `<article class="chart-card">
      <div class="chart-topline"><span class="chart-number">${String(index + 1).padStart(2,"0")}</span><h4>${question[0]}</h4></div>
      ${rows}
    </article>`;
  }).join("");
}

